 for t in out:
  if t[0]=='const': cols.append(np.ones(len(X)))
  elif t[0]=='linear': cols.append(X[:,t[1]])
  elif t[0]=='hinge': cols.append(np.maximum(X[:,t[1]]-t[2],0))
  elif t[0]=='pair': cols.append(X[:,t[1]]*X[:,t[2]])
  else: cols.append(np.maximum(X[:,t[1]]-t[3],0)*np.maximum(X[:,t[2]]-t[4],0))
 return np.column_stack(cols)

